def check_valid(n):
    if n <= 0:
        return False

    s_n = str(n)

    # Check condition ii): Digits must be in {0, 1, 2, 8}
    allowed_digits = {'0', '1', '2', '8'}
    for digit in s_n:
        if digit not in allowed_digits:
            return False

    # Check condition i): 3 | n
    if n % 3 != 0:
        return False

    # Determine length L
    L = len(s_n)
    return L

# Check for L=1, L=2, L=3
count_L1 = 0
count_L2 = 0
count_L3 = 0

# L=1: n in [1, 9]
for n in range(1, 10):
    if check_valid(n):
        count_L1 += 1

# L=2: n in [10, 99]
for n in range(10, 100):
    if check_valid(n):
        count_L2 += 1

# L=3: n in [100, 999]
for n in range(100, 1000):
    if check_valid(n):
        count_L3 += 1

print(f"Count for L=1: {count_L1}")
print(f"Count for L=2: {count_L2}")
print(f"Count for L=3: {count_L3}")
